import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Фермерская лавка: предзаказ продуктов на выходные с доставкой по городу в интервал"}>
      <p>{"Мы фермерское хозяйство под Владимиром: молоко, творог, сыры, яйца, мясо птицы, овощи по сезону. Продаём через чат, заказы теряются. Нужен магазин предзаказа: каталог с разделами и ценой за штуку или за килограмм, у весовых товаров цена примерная, точную сумму считаем после взвешивания. Заказы принимаем до четверга двадцати часов, привозим в субботу или воскресенье в выбранный двухчасовой интервал по городу, в каждом интервале не больше пятнадцати заказов. Минимальный заказ — полторы тысячи рублей. Покупатель платит картой при оформлении через ЮKassa, а если после взвешивания вышло дешевле — возвращаем разницу, дороже — не берём доплату. Можно забрать самому с фермы в субботу. Покупатель видит свои заказы и может повторить прошлый заказ одной кнопкой. Мы в кабинете видим сборку на выходные: сколько чего собрать, заказы по интервалам, и отмечаем «собран» и «доставлен». Хотим простой сайт без лишнего, с фото фермы. Ресторанам мы пишем через клиент, её телеграм клиент."}</p>
      <ul>
        <li>{"Корзина и оформление"}</li>
        <li>{"Выбор интервала доставки"}</li>
        <li>{"Оплата ЮKassa и возврат разницы"}</li>
        <li>{"Повтор прошлого заказа"}</li>
        <li>{"Сборка на выходные"}</li>
      </ul>
      <p>{"Не больше 15 заказов в интервале"}</p>
      <p>{"Минимальный заказ 1 500 ₽"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
